<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class EmployeeController extends Controller{public function index(Request $r){$q=DB::table('employees');if($s=trim((string)$r->query('search','')))$q->where(fn($x)=>$x->where('full_name','like',"%$s%")->orWhere('employee_no','like',"%$s%"));return $q->orderBy('full_name')->paginate($r->integer('per_page',20));}public function store(Request $r){$d=$this->v($r);$id=DB::table('employees')->insertGetId($d);return response()->json(DB::table('employees')->find($id),201);}public function update(Request $r,int $employee){DB::table('employees')->where('id',$employee)->update($this->v($r,$employee));return DB::table('employees')->find($employee);}public function show(int $employee){return DB::table('employees')->find($employee)??abort(404);}public function destroy(int $employee){DB::table('employees')->where('id',$employee)->update(['employment_status'=>'Terminated']);return response()->noContent();}private function v(Request $r,$id=null){$d=$r->validate(['employee_code'=>['required','string','max:40',Rule::unique('employees','employee_no')->ignore($id)],'name'=>'required|string|max:120','email'=>'nullable|email','phone'=>'nullable|string|max:40','position'=>'nullable|string|max:80','department'=>'nullable|string|max:80','status'=>'required|in:active,inactive','pay_type'=>'required|in:monthly,hourly','basic_salary'=>'nullable|numeric|min:0','hourly_rate'=>'nullable|numeric|min:0','leave_balance'=>'nullable|numeric|min:0']);return['employee_no'=>$d['employee_code'],'full_name'=>$d['name'],'email'=>$d['email']??null,'phone'=>$d['phone']??null,'position'=>$d['position']?:'Staff','department'=>$d['department']?:'General','hire_date'=>date('Y-m-d'),'employment_status'=>$d['status']==='active'?'Active':'Terminated','pay_type'=>$d['pay_type']==='hourly'?'Hourly':'Monthly','basic_salary'=>$d['basic_salary']??0,'hourly_rate'=>$d['hourly_rate']??0,'leave_balance'=>$d['leave_balance']??15];}}